<script setup>
import { computed, reactive } from 'vue'
const props=defineProps({baseUrl:{type:String,required:true},token:{type:String,required:true},items:{type:Array,default:()=>[]}})
const emit=defineEmits(['changed','notify'])
const ui=reactive({open:false,editing:null,busy:false,testInput:'{\n  "text": "Powflow"\n}',testResult:'',error:''})
const form=reactive({name:'',description:'',code:'return { message: `你好，${input.text}` };',inputSchema:'{\n  "type": "object",\n  "properties": { "text": { "type": "string" } },\n  "required": ["text"],\n  "additionalProperties": false\n}',outputSchema:'{\n  "type": "object",\n  "properties": { "message": { "type": "string" } },\n  "required": ["message"]\n}',allowAgent:true,allowWorkflow:true,riskLevel:'COMPUTE',timeoutMs:1000,memoryMb:16})
const published=computed(()=>props.items.filter(x=>x.latest_version_no>0).length)
function headers(){return{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'}}
async function request(path,options={}){const r=await fetch(`${props.baseUrl.replace(/\/$/,'')}${path}`,{method:options.method||'GET',headers:headers(),body:options.body?JSON.stringify(options.body):undefined});const text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch{}if(!r.ok)throw new Error(data.detail||'操作未能完成');return data}
function open(item=null){ui.editing=item;ui.testResult='';ui.error='';const d=item?.draft_definition||{};Object.assign(form,item?{name:item.name,description:item.description,code:d.code||'',inputSchema:JSON.stringify(d.input_schema||{type:'object'},null,2),outputSchema:JSON.stringify(d.output_schema||{type:'object'},null,2),allowAgent:d.allow_agent!==false,allowWorkflow:d.allow_workflow!==false,riskLevel:d.risk_level||'COMPUTE',timeoutMs:d.timeout_ms||1000,memoryMb:d.memory_mb||16}:{name:'',description:'',code:'return { message: `你好，${input.text}` };',inputSchema:'{\n  "type": "object",\n  "properties": { "text": { "type": "string" } },\n  "required": ["text"],\n  "additionalProperties": false\n}',outputSchema:'{\n  "type": "object",\n  "properties": { "message": { "type": "string" } },\n  "required": ["message"]\n}',allowAgent:true,allowWorkflow:true,riskLevel:'COMPUTE',timeoutMs:1000,memoryMb:16});ui.open=true}
function jsonValue(v,label){try{return JSON.parse(v)}catch{throw new Error(`${label}不是有效 JSON`)}}
function payload(){return{name:form.name,description:form.description,code:form.code,input_schema:jsonValue(form.inputSchema,'输入 Schema'),output_schema:jsonValue(form.outputSchema,'输出 Schema'),allow_agent:form.allowAgent,allow_workflow:form.allowWorkflow,risk_level:form.riskLevel,timeout_ms:Number(form.timeoutMs),memory_mb:Number(form.memoryMb)}}
async function save(){ui.busy=true;ui.error='';try{const path=ui.editing?`/api/v1/javascript-tools/${ui.editing.tool_id}`:'/api/v1/javascript-tools';const data=await request(path,{method:ui.editing?'PUT':'POST',body:payload()});ui.editing=data.item;emit('changed');emit('notify',{type:'success',title:'工具草稿已保存',message:'现在可以测试或发布。'})}catch(e){ui.error=e.message}finally{ui.busy=false}}
async function test(){if(!ui.editing)await save();if(!ui.editing)return;ui.busy=true;ui.error='';try{const data=await request(`/api/v1/javascript-tools/${ui.editing.tool_id}/test`,{method:'POST',body:{arguments:jsonValue(ui.testInput,'测试参数')}});ui.testResult=JSON.stringify(data.item?.output,null,2)}catch(e){ui.error=e.message}finally{ui.busy=false}}
async function publish(){if(!ui.editing)return;ui.busy=true;ui.error='';try{await request(`/api/v1/javascript-tools/${ui.editing.tool_id}/publish`,{method:'POST'});emit('changed');ui.open=false;emit('notify',{type:'success',title:'工具已发布',message:'AI 和 Workflow 将使用不可变版本快照。'})}catch(e){ui.error=e.message}finally{ui.busy=false}}
async function remove(item){if(!confirm(`删除工具“${item.name}”？`))return;try{await request(`/api/v1/javascript-tools/${item.tool_id}`,{method:'DELETE'});emit('changed');emit('notify',{type:'success',title:'工具已删除',message:''})}catch(e){emit('notify',{type:'error',title:'删除失败',message:e.message})}}
</script>
<template><section class="tool-page"><header class="tool-hero"><div><span>FUNCTION REGISTRY</span><h2>工具工作台</h2><p>用受控 JavaScript 把业务计算封装为 AI 与 Workflow 可调用的函数。</p></div><button @click="open()">＋ 添加工具</button></header><div class="tool-metrics"><article><b>{{ items.length }}</b><span>全部工具</span></article><article><b>{{ published }}</b><span>已发布</span></article><article><b>{{ items.filter(x=>x.draft_definition?.allow_agent).length }}</b><span>AI 可用</span></article><article><b>{{ items.filter(x=>x.draft_definition?.allow_workflow).length }}</b><span>Workflow 可用</span></article></div><div class="tool-grid"><button class="create-card" @click="open()"><i>＋</i><strong>创建 JavaScript 工具</strong><small>定义输入、函数和输出</small></button><article v-for="item in items" :key="item.tool_id" class="tool-card"><div class="card-top"><span class="js-mark">JS</span><span :class="['status',item.status.toLowerCase()]">{{ item.latest_version_no>0?`v${item.latest_version_no}`:'草稿' }}</span></div><h3>{{ item.name }}</h3><p>{{ item.description||'尚未填写工具用途说明。' }}</p><div class="scope-track"><span :class="{on:item.draft_definition?.allow_agent}">AI</span><i></i><span :class="{on:item.draft_definition?.allow_workflow}">Workflow</span></div><footer><button @click="open(item)">打开工作台</button><button class="danger" @click="remove(item)">删除</button></footer></article></div><div v-if="ui.open" class="modal-mask" @keydown.esc="ui.open=false"><section class="editor-modal"><header><div><span>JAVASCRIPT TOOL</span><h2>{{ ui.editing?'编辑工具':'添加工具' }}</h2></div><button @click="ui.open=false">×</button></header><div class="editor-layout"><main><div class="two"><label>名称<input v-model="form.name" maxlength="128" /></label><label>风险等级<select v-model="form.riskLevel"><option value="READ_ONLY">只读</option><option value="COMPUTE">纯计算</option><option value="WRITE">写操作</option></select></label></div><label>用途说明<textarea v-model="form.description" rows="2" /></label><label>函数体 <small>参数对象为 input，请使用 return 返回 JSON 可序列化结果。</small><textarea v-model="form.code" class="code" rows="11" spellcheck="false" /></label><div class="two"><label>输入 Schema<textarea v-model="form.inputSchema" class="code small" rows="10" /></label><label>输出 Schema<textarea v-model="form.outputSchema" class="code small" rows="10" /></label></div></main><aside><h3>使用范围</h3><label class="scope-switch"><div><b>智能体 / AI</b><small>模型可按 Schema 自主调用</small></div><input v-model="form.allowAgent" type="checkbox" /></label><label class="scope-switch"><div><b>Workflow</b><small>可作为画布工具节点</small></div><input v-model="form.allowWorkflow" type="checkbox" /></label><div class="two"><label>超时 ms<input v-model.number="form.timeoutMs" type="number" min="10" max="5000" /></label><label>内存 MB<input v-model.number="form.memoryMb" type="number" min="4" max="64" /></label></div><h3>运行测试</h3><label>输入参数<textarea v-model="ui.testInput" class="code small" rows="7" /></label><pre v-if="ui.testResult">{{ ui.testResult }}</pre><p v-if="ui.error" class="error">{{ ui.error }}</p></aside></div><footer><button class="secondary" :disabled="ui.busy" @click="save">保存草稿</button><button class="secondary" :disabled="ui.busy" @click="test">运行测试</button><button class="primary" :disabled="ui.busy||!ui.editing" @click="publish">发布版本</button></footer></section></div></section></template>
<style scoped>.tool-page{display:grid;gap:18px}.tool-hero{display:flex;align-items:end;justify-content:space-between;padding:26px;border:1px solid var(--workspace-border);border-radius:24px;background:radial-gradient(circle at 85% 10%,rgba(50,215,75,.13),transparent 32%),var(--workspace-panel)}.tool-hero span,.editor-modal header span{color:#32d74b;font:700 10px ui-monospace;letter-spacing:.15em}.tool-hero h2{margin:8px 0 4px;font-size:28px}.tool-hero p{margin:0;color:var(--workspace-muted)}button{border:0;cursor:pointer}.tool-hero button,.primary{padding:11px 16px;border-radius:12px;color:#071108;background:#32d74b;font-weight:750}.tool-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.tool-metrics article{display:grid;gap:3px;padding:16px;border:1px solid var(--workspace-border);border-radius:16px;background:var(--workspace-panel)}.tool-metrics b{font-size:22px}.tool-metrics span{color:var(--workspace-muted);font-size:12px}.tool-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}.tool-card,.create-card{min-height:220px;padding:18px;border:1px solid var(--workspace-border);border-radius:20px;text-align:left;color:var(--workspace-text);background:var(--workspace-panel)}.create-card{display:grid;place-content:center;justify-items:center;gap:7px;border-style:dashed}.create-card i{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;color:#32d74b;background:rgba(50,215,75,.1);font-size:25px}.create-card small,.tool-card p{color:var(--workspace-muted)}.card-top,.tool-card footer{display:flex;align-items:center;justify-content:space-between}.js-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;color:#061208;background:#32d74b;font:800 12px ui-monospace}.status{padding:5px 8px;border-radius:99px;color:var(--workspace-muted);background:rgba(127,127,127,.1);font-size:10px}.status.published{color:#32d74b;background:rgba(50,215,75,.1)}.tool-card h3{margin:17px 0 7px}.tool-card p{min-height:38px;font-size:12px}.scope-track{display:flex;align-items:center;margin:20px 0}.scope-track span{padding:5px 8px;border-radius:8px;color:var(--workspace-muted);background:rgba(127,127,127,.08);font-size:10px}.scope-track span.on{color:#32d74b;background:rgba(50,215,75,.1)}.scope-track i{flex:1;height:1px;background:var(--workspace-border)}.tool-card footer button,.secondary{padding:8px 10px;border-radius:9px;color:var(--workspace-text);background:rgba(127,127,127,.1)}.danger{color:#ff6961!important;background:transparent!important}.modal-mask{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:20px;background:rgba(0,0,0,.62);backdrop-filter:blur(14px)}.editor-modal{width:min(1180px,96vw);max-height:94vh;overflow:auto;border:1px solid var(--workspace-border);border-radius:25px;color:var(--workspace-text);background:var(--workspace-panel-solid,#1c1c1e);box-shadow:0 30px 90px rgba(0,0,0,.4)}.editor-modal>header,.editor-modal>footer{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--workspace-border)}.editor-modal>footer{justify-content:flex-end;gap:9px;border-top:1px solid var(--workspace-border);border-bottom:0}.editor-modal h2{margin:4px 0 0}.editor-modal header button{color:var(--workspace-text);background:transparent;font-size:28px}.editor-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.7fr);gap:20px;padding:22px}.editor-layout aside{padding:16px;border-radius:17px;background:rgba(127,127,127,.06)}label{display:grid;gap:7px;margin-bottom:13px;color:var(--workspace-muted);font-size:12px}input,select,textarea{box-sizing:border-box;width:100%;padding:10px 11px;border:1px solid var(--workspace-border);border-radius:11px;color:var(--workspace-text);background:rgba(127,127,127,.09);outline:none}textarea{resize:none}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.code,pre{font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.scope-switch{display:flex;align-items:center;justify-content:space-between;padding:12px;border-radius:13px;background:rgba(127,127,127,.06)}.scope-switch div{display:grid;gap:3px}.scope-switch b{color:var(--workspace-text)}.scope-switch input{width:18px}.editor-layout h3{margin:4px 0 12px;font-size:14px}pre{max-height:180px;overflow:auto;padding:12px;border-radius:12px;color:#32d74b;background:#070b08}.error{color:#ff6961;font-size:12px}:global(html[data-theme=dark] .tool-page select){color-scheme:dark;color:#f5f5f7;background:#2b2b2e}:global(html[data-theme=dark] .tool-page option){color:#f5f5f7;background:#242426}:global(html[data-theme=light] .tool-page select){color-scheme:light;color:#1d1d1f;background:#fff}:global(html[data-theme=light] .tool-page option){color:#1d1d1f;background:#fff}@media(max-width:800px){.tool-metrics{grid-template-columns:1fr 1fr}.editor-layout{grid-template-columns:1fr}.tool-hero{align-items:start;flex-direction:column;gap:16px}.two{grid-template-columns:1fr}}</style>
